mapper.select:
SELECT t1.id, t1.`code`, t1.visualization_code, t1.master_name, t1.master_phone, t1.`name`, t1.type, t1.area, t1.location, t1.built_up_area, t1.practical_area, t1.dept_id, t1.dept_name, t1.lease_type, t1.leased, t1.remark, t1.enabled FROM `stall` t1 INNER JOIN business_scene_config t2 ON t1.id = t2.business_id
and t2.scene_type = #{param.sceneType}
and (t1.code like concat('%',#{param.keyword},'%') or t1.name like concat('%',#{param.keyword},'%') or t1.visualization_code like concat('%',#{param.keyword},'%') )
and t1.area like concat('%',#{param.areaId},'%')
and t1.type = #{param.categoryId}
and t1.enabled = #{param.enabled}
order by t1.create_time desc

SELECT t1.id, t1.`code`, t1.visualization_code, t1.master_name, t1.master_phone, t1.`name`, t1.type, t1.area, t1.location, t1.built_up_area, t1.practical_area, t1.dept_id, t1.dept_name, t1.lease_type, t1.leased, t1.remark, t1.enabled FROM `stall` t1
and t1.id not in ( SELECT business_id FROM business_scene_config WHERE scene_type = #{param.sceneType}
and project_id = #{param.projectId}
)
and (t1.code like concat('%',#{param.keyword},'%') or t1.name like concat('%',#{param.keyword},'%') or t1.visualization_code like concat('%',#{param.keyword},'%') )
and t1.area like concat('%',#{param.areaId},'%')
and t1.type = #{param.categoryId}
and t1.enabled = #{param.enabled}
order by t1.create_time desc

